{"content": "     1|<!DOCTYPE html>
     2|<html lang="id">
     3|<head>
     4|<meta charset="UTF-8">
     5|<meta name="viewport" content="width=device-width, initial-scale=1.0">
     6|<title>Arsify — AI Infrastructure by Upshalter</title>
     7|<meta name="description" content="Arsify adalah ekosistem AI lokal yang ditenagai Arsiparis — AI Context Librarian yang menyatukan memori, orkestrat agen, dan marketing dalam satu infrastruktur yang kamu kuasai sepenuhnya.">
     8|<link rel="preconnect" href="https://fonts.googleapis.com">
     9|<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    10|<link href="https://fonts.googleapis.com/css2?family=Space+Mono:ital,wght@0,400;0,700;1,400&family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;1,9..40,300&display=swap" rel="stylesheet">
    11|<style>
    12|:root {
    13|  --purple: #534AB7;
    14|  --purple-dark: #26215C;
    15|  --purple-mid: #3C3489;
    16|  --purple-light: #EEEDFE;
    17|  --purple-muted: #AFA9EC;
    18|  --teal: #0F6E56;
    19|  --teal-light: #E1F5EE;
    20|  --teal-mid: #1D9E75;
    21|  --amber: #BA7517;
    22|  --amber-light: #FAEEDA;
    23|  --amber-mid: #EF9F27;
    24|  --bg: #07060F;
    25|  --bg2: #0D0B1A;
    26|  --bg3: #110F22;
    27|  --surface: #141228;
    28|  --surface2: #1A1832;
    29|  --surface3: #1F1C3A;
    30|  --border: rgba(83,74,183,0.2);
    31|  --border-dim: rgba(255,255,255,0.06);
    32|  --border-teal: rgba(15,110,86,0.3);
    33|  --text: #E8E6F4;
    34|  --text-muted: #8A87AB;
    35|  --text-dim: #4E4C6A;
    36|  --mono: 'Space Mono', monospace;
    37|  --sans: 'DM Sans', sans-serif;
    38|  --grid-px: rgba(83,74,183,0.035);
    39|}
    40|
    41|*,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}
    42|html{scroll-behavior:smooth;}
    43|body{background:var(--bg);color:var(--text);font-family:var(--sans);font-size:16px;line-height:1.7;overflow-x:hidden;}
    44|
    45|body::before{
    46|  content:'';position:fixed;inset:0;
    47|  background-image:linear-gradient(var(--grid-px) 1px,transparent 1px),linear-gradient(90deg,var(--grid-px) 1px,transparent 1px);
    48|  background-size:48px 48px;pointer-events:none;z-index:0;
    49|}
    50|
    51|::-webkit-scrollbar{width:4px;}
    52|::-webkit-scrollbar-track{background:var(--bg);}
    53|::-webkit-scrollbar-thumb{background:var(--purple-dark);border-radius:2px;}
    54|
    55|/* ── NAV ── */
    56|nav{
    57|  position:fixed;top:0;left:0;right:0;z-index:100;
    58|  padding:0 48px;height:60px;
    59|  display:flex;align-items:center;justify-content:space-between;
    60|  background:rgba(7,6,15,0.9);backdrop-filter:blur(16px);
    61|  border-bottom:1px solid var(--border-dim);
    62|  transition:border-color 0.3s;
    63|}
    64|.nav-brand{display:flex;align-items:center;gap:0;text-decoration:none;}
    65|.nav-brand-arsify{font-family:var(--mono);font-size:16px;font-weight:700;color:var(--text);letter-spacing:-0.03em;}
    66|.nav-brand-arsify em{font-style:normal;color:var(--purple-muted);}
    67|.nav-brand-sub{font-family:var(--mono);font-size:11px;color:var(--text-dim);margin-left:2px;letter-spacing:0.04em;}
    68|.nav-divider{width:1px;height:20px;background:var(--border-dim);margin:0 20px;}
    69|.nav-parent{font-family:var(--mono);font-size:11px;color:var(--text-dim);text-decoration:none;letter-spacing:0.06em;}
    70|.nav-parent:hover{color:var(--text-muted);}
    71|.nav-links{display:flex;align-items:center;gap:28px;list-style:none;}
    72|.nav-links a{font-family:var(--mono);font-size:11px;color:var(--text-muted);text-decoration:none;letter-spacing:0.06em;text-transform:uppercase;transition:color 0.2s;}
    73|.nav-links a:hover{color:var(--text);}
    74|.nav-cta{font-family:var(--mono);font-size:11px;color:var(--purple-light);border:1px solid var(--purple);padding:6px 16px;border-radius:4px;text-decoration:none;letter-spacing:0.06em;transition:background 0.2s,color 0.2s;}
    75|.nav-cta:hover{background:var(--purple);color:#fff;}
    76|
    77|/* ── SECTION ── */
    78|section{position:relative;z-index:1;padding:100px 0;}
    79|.container{max-width:1100px;margin:0 auto;padding:0 48px;}
    80|.container-wide{max-width:1280px;margin:0 auto;padding:0 48px;}
    81|
    82|.section-divider{
    83|  position:relative;z-index:1;
    84|  height:1px;background:linear-gradient(90deg,transparent,var(--border),transparent);
    85|  margin:0 48px;
    86|}
    87|
    88|/* ── LABELS ── */
    89|.label{font-family:var(--mono);font-size:11px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-dim);display:flex;align-items:center;gap:10px;margin-bottom:20px;}
    90|.label::before{content:'';width:24px;height:1px;background:var(--text-dim);display:inline-block;}
    91|.label-purple{color:var(--purple);}
    92|.label-purple::before{background:var(--purple);}
    93|.label-teal{color:var(--teal-mid);}
    94|.label-teal::before{background:var(--teal-mid);}
    95|.label-amber{color:var(--amber-mid);}
    96|.label-amber::before{background:var(--amber-mid);}
    97|
    98|/* ── TYPOGRAPHY ── */
    99|h1,h2,h3,h4{font-family:var(--mono);line-height:1.15;letter-spacing:-0.02em;}
   100|h1{font-size:clamp(38px,5.5vw,72px);font-weight:700;}
   101|h2{font-size:clamp(28px,3.5vw,46px);font-weight:700;}
   102|h3{font-size:clamp(17px,2vw,22px);font-weight:700;}
   103|h4{font-size:13px;font-weight:700;letter-spacing:0.06em;text-transform:uppercase;}
   104|
   105|/* ── REVEAL ── */
   106|.reveal{opacity:0;transform:translateY(24px);transition:opacity 0.6s ease,transform 0.6s ease;}
   107|.reveal.visible{opacity:1;transform:none;}
   108|.reveal-delay-1{transition-delay:0.1s;}
   109|.reveal-delay-2{transition-delay:0.2s;}
   110|.reveal-delay-3{transition-delay:0.3s;}
   111|.reveal-delay-4{transition-delay:0.4s;}
   112|
   113|/* ═══════════════════ HERO ═══════════════════ */
   114|#hero{
   115|  min-height:100vh;display:flex;flex-direction:column;justify-content:center;
   116|  padding:120px 0 80px;position:relative;overflow:hidden;
   117|}
   118|#hero::before{
   119|  content:'';position:absolute;top:-300px;left:50%;transform:translateX(-50%);
   120|  width:900px;height:900px;
   121|  background:radial-gradient(circle,rgba(83,74,183,0.14) 0%,transparent 65%);
   122|  pointer-events:none;
   123|}
   124|#hero::after{
   125|  content:'';position:absolute;bottom:-100px;right:-100px;
   126|  width:500px;height:500px;
   127|  background:radial-gradient(circle,rgba(15,110,86,0.08) 0%,transparent 65%);
   128|  pointer-events:none;
   129|}
   130|.hero-eyebrow{
   131|  display:inline-flex;align-items:center;gap:10px;
   132|  background:rgba(83,74,183,0.1);border:1px solid rgba(83,74,183,0.25);
   133|  border-radius:4px;padding:5px 14px;margin-bottom:40px;
   134|  font-family:var(--mono);font-size:11px;color:var(--purple-light);letter-spacing:0.1em;
   135|}
   136|.hero-eyebrow-dot{width:6px;height:6px;border-radius:50%;background:var(--teal-mid);animation:pulse 2.4s infinite;}
   137|@keyframes pulse{0%,100%{opacity:1;transform:scale(1);}50%{opacity:0.4;transform:scale(0.7);}}
   138|
   139|.hero-title{color:var(--text);margin-bottom:8px;}
   140|.hero-title-alt{
   141|  font-family:var(--mono);font-size:clamp(38px,5.5vw,72px);font-weight:700;
   142|  line-height:1.15;letter-spacing:-0.02em;
   143|  color:var(--purple-muted);margin-bottom:28px;
   144|}
   145|.hero-lead{
   146|  font-size:clamp(15px,1.5vw,18px);color:var(--text-muted);
   147|  max-width:560px;margin-bottom:48px;line-height:1.8;
   148|}
   149|.hero-lead strong{color:var(--text);font-weight:500;}
   150|.hero-actions{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:80px;}
   151|.btn-primary{
   152|  font-family:var(--mono);font-size:12px;background:var(--purple);color:#fff;
   153|  border:none;padding:13px 28px;border-radius:4px;cursor:pointer;
   154|  text-decoration:none;letter-spacing:0.06em;transition:background 0.2s,transform 0.15s;
   155|}
   156|.btn-primary:hover{background:var(--purple-mid);transform:translateY(-1px);}
   157|.btn-ghost{
   158|  font-family:var(--mono);font-size:12px;color:var(--text-muted);
   159|  border:1px solid var(--border-dim);padding:13px 28px;border-radius:4px;
   160|  cursor:pointer;text-decoration:none;letter-spacing:0.06em;transition:border-color 0.2s,color 0.2s;
   161|}
   162|.btn-ghost:hover{border-color:rgba(255,255,255,0.2);color:var(--text);}
   163|
   164|.hero-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--border-dim);border-radius:6px;overflow:hidden;}
   165|.hero-stat{background:var(--bg2);padding:20px 24px;}
   166|.hero-stat-num{font-family:var(--mono);font-size:28px;font-weight:700;color:var(--text);line-height:1;margin-bottom:6px;}
   167|.hero-stat-num.teal{color:var(--teal-mid);}
   168|.hero-stat-num.amber{color:var(--amber-mid);}
   169|.hero-stat-num.purple{color:var(--purple-muted);}
   170|.hero-stat-label{font-family:var(--mono);font-size:10px;color:var(--text-dim);letter-spacing:0.08em;text-transform:uppercase;}
   171|
   172|/* ═══════════════════ ARSIPARIS CORE ═══════════════════ */
   173|.arsiparis-section{background:var(--bg2);border-top:1px solid var(--border-dim);border-bottom:1px solid var(--border-dim);}
   174|.arsiparis-layout{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center;margin-top:60px;}
   175|.arsiparis-visual{
   176|  background:var(--surface);border:1px solid var(--border);border-radius:8px;
   177|  padding:32px;font-family:var(--mono);position:relative;overflow:hidden;
   178|}
   179|.arsiparis-visual::before{
   180|  content:'';position:absolute;top:0;left:0;right:0;height:2px;
   181|  background:linear-gradient(90deg,transparent,var(--purple),transparent);
   182|}
   183|.ars-title{font-size:10px;color:var(--text-dim);letter-spacing:0.1em;text-transform:uppercase;margin-bottom:24px;}
   184|.ars-core{
   185|  text-align:center;padding:24px;
   186|  background:rgba(83,74,183,0.08);border:1px solid rgba(83,74,183,0.25);
   187|  border-radius:6px;margin-bottom:16px;
   188|}
   189|.ars-core-name{font-size:18px;font-weight:700;color:var(--purple-muted);margin-bottom:4px;}
   190|.ars-core-desc{font-size:10px;color:var(--text-dim);letter-spacing:0.06em;}
   191|.ars-arrow{text-align:center;color:var(--text-dim);font-size:12px;margin:8px 0;}
   192|.ars-agents{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;}
   193|.ars-agent{
   194|  background:var(--bg3);border:1px solid var(--border-dim);border-radius:4px;
   195|  padding:10px 8px;text-align:center;
   196|}
   197|.ars-agent-dot{width:6px;height:6px;border-radius:50%;background:var(--teal-mid);margin:0 auto 6px;}
   198|.ars-agent-name{font-size:9px;color:var(--text-muted);letter-spacing:0.04em;}
   199|.ars-metrics{margin-top:16px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;}
   200|.ars-metric{background:var(--bg3);border:1px solid var(--border-dim);border-radius:4px;padding:10px 8px;text-align:center;}
   201|.ars-metric-num{font-size:14px;font-weight:700;color:var(--teal-mid);margin-bottom:2px;}
   202|.ars-metric-lbl{font-size:8px;color:var(--text-dim);letter-spacing:0.06em;text-transform:uppercase;}
   203|
   204|.arsiparis-text{}
   205|.arsiparis-text h2{margin-bottom:20px;}
   206|.arsiparis-body{color:var(--text-muted);margin-bottom:24px;line-height:1.8;}
   207|.arsiparis-body strong{color:var(--text);font-weight:500;}
   208|.arsiparis-quote{
   209|  border-left:2px solid var(--purple);padding-left:20px;
   210|  font-family:var(--mono);font-size:13px;color:var(--purple-muted);
   211|  line-height:1.7;margin-bottom:28px;
   212|}
   213|.arsiparis-props{display:flex;flex-direction:column;gap:10px;}
   214|.ars-prop{display:flex;align-items:flex-start;gap:12px;}
   215|.ars-prop-icon{width:20px;height:20px;border-radius:3px;background:rgba(83,74,183,0.15);border:1px solid rgba(83,74,183,0.3);flex-shrink:0;margin-top:2px;display:flex;align-items:center;justify-content:center;}
   216|.ars-prop-icon svg{width:10px;height:10px;fill:var(--purple-muted);}
   217|.ars-prop-text{font-size:14px;color:var(--text-muted);line-height:1.6;}
   218|.ars-prop-text strong{color:var(--text);font-weight:500;}
   219|
   220|/* ═══════════════════ PRODUCTS ═══════════════════ */
   221|.products-grid{display:flex;flex-direction:column;gap:2px;margin-top:60px;}
   222|.product-card{
   223|  background:var(--bg2);border:1px solid var(--border-dim);border-radius:8px;
   224|  overflow:hidden;transition:border-color 0.3s;
   225|}
   226|.product-card:hover{border-color:var(--border);}
   227|.product-card-inner{display:grid;grid-template-columns:1fr 1fr;min-height:320px;}
   228|.product-card-inner.reverse{direction:rtl;}
   229|.product-card-inner.reverse > *{direction:ltr;}
   230|
   231|.product-info{padding:48px;display:flex;flex-direction:column;justify-content:center;}
   232|.product-badge{
   233|  display:inline-flex;align-items:center;gap:8px;
   234|  font-family:var(--mono);font-size:10px;letter-spacing:0.1em;text-transform:uppercase;
   235|  padding:4px 10px;border-radius:3px;width:fit-content;margin-bottom:20px;
   236|}
   237|.badge-os{background:rgba(83,74,183,0.12);color:var(--purple-muted);border:1px solid rgba(83,74,183,0.25);}
   238|.badge-browser{background:rgba(15,110,86,0.12);color:#5DCAA5;border:1px solid rgba(15,110,86,0.25);}
   239|.badge-vox{background:rgba(186,117,23,0.12);color:var(--amber-mid);border:1px solid rgba(186,117,23,0.25);}
   240|.badge-dot{width:5px;height:5px;border-radius:50%;}
   241|.dot-os{background:var(--purple-muted);}
   242|.dot-browser{background:#5DCAA5;}
   243|.dot-vox{background:var(--amber-mid);}
   244|
   245|.product-name{font-family:var(--mono);font-size:clamp(22px,2.5vw,32px);font-weight:700;color:var(--text);margin-bottom:4px;letter-spacing:-0.02em;}
   246|.product-tagline{font-family:var(--mono);font-size:13px;color:var(--text-dim);margin-bottom:20px;letter-spacing:0.02em;}
   247|.product-desc{font-size:15px;color:var(--text-muted);line-height:1.8;margin-bottom:28px;}
   248|.product-desc strong{color:var(--text);font-weight:500;}
   249|.product-features{display:flex;flex-direction:column;gap:8px;margin-bottom:32px;}
   250|.product-feature{display:flex;align-items:center;gap:10px;font-size:13px;color:var(--text-muted);}
   251|.product-feature::before{content:'';width:4px;height:4px;border-radius:50%;background:currentColor;flex-shrink:0;margin-top:1px;}
   252|.product-eta{font-family:var(--mono);font-size:10px;color:var(--text-dim);letter-spacing:0.08em;padding:6px 12px;border:1px solid var(--border-dim);border-radius:3px;width:fit-content;}
   253|
   254|.product-visual{background:var(--bg3);padding:40px 36px;display:flex;flex-direction:column;justify-content:center;border-left:1px solid var(--border-dim);}
   255|.product-card-inner.reverse .product-visual{border-left:none;border-right:1px solid var(--border-dim);}
   256|
   257|/* OS Visual */
   258|.os-stack{font-family:var(--mono);font-size:11px;}
   259|.os-layer{
   260|  border:1px solid var(--border-dim);border-radius:4px;
   261|  padding:12px 16px;margin-bottom:8px;
   262|  background:var(--surface);
   263|}
   264|.os-layer-label{font-size:9px;color:var(--text-dim);letter-spacing:0.1em;text-transform:uppercase;margin-bottom:8px;}
   265|.os-layer-chips{display:flex;flex-wrap:wrap;gap:6px;}
   266|.os-chip{
   267|  padding:3px 8px;border-radius:3px;font-size:9px;
   268|  background:rgba(83,74,183,0.1);color:var(--purple-muted);
   269|  border:1px solid rgba(83,74,183,0.2);letter-spacing:0.04em;
   270|}
   271|.os-chip.teal{background:rgba(15,110,86,0.1);color:#5DCAA5;border-color:rgba(15,110,86,0.2);}
   272|.os-chip.dim{background:var(--bg3);color:var(--text-dim);border-color:var(--border-dim);}
   273|.os-connector{text-align:center;font-size:10px;color:var(--text-dim);padding:4px 0;}
   274|
   275|/* Browser Visual */
   276|.browser-agents{display:flex;flex-direction:column;gap:8px;font-family:var(--mono);}
   277|.browser-agent-row{
   278|  display:flex;align-items:center;gap:10px;
   279|  background:var(--surface);border:1px solid var(--border-dim);border-radius:4px;
   280|  padding:10px 14px;
   281|}
   282|.browser-agent-indicator{width:6px;height:6px;border-radius:50%;flex-shrink:0;}
   283|.ind-active{background:#5DCAA5;animation:pulse 2s infinite;}
   284|.ind-idle{background:var(--text-dim);}
   285|.browser-agent-name{font-size:10px;color:var(--text-muted);flex:1;}
   286|.browser-agent-status{font-size:9px;color:var(--text-dim);}
   287|.browser-agent-status.done{color:#5DCAA5;}
   288|.browser-pool{
   289|  margin-top:12px;background:rgba(15,110,86,0.06);border:1px solid rgba(15,110,86,0.2);
   290|  border-radius:4px;padding:12px 14px;
   291|}
   292|.browser-pool-label{font-size:9px;color:#5DCAA5;letter-spacing:0.1em;text-transform:uppercase;margin-bottom:6px;}
   293|.browser-pool-bar{height:4px;background:var(--bg3);border-radius:2px;overflow:hidden;margin-bottom:6px;}
   294|.browser-pool-fill{height:100%;width:73%;background:linear-gradient(90deg,#1D9E75,#5DCAA5);border-radius:2px;}
   295|.browser-pool-stat{font-size:9px;color:var(--text-dim);}
   296|
   297|/* Vox Visual */
   298|.vox-brain{font-family:var(--mono);}
   299|.vox-brain-header{
   300|  background:rgba(186,117,23,0.08);border:1px solid rgba(186,117,23,0.25);
   301|  border-radius:4px;padding:14px 16px;margin-bottom:12px;
   302|  text-align:center;
   303|}
   304|.vox-brain-title{font-size:14px;font-weight:700;color:var(--amber-mid);margin-bottom:2px;}
   305|.vox-brain-sub{font-size:9px;color:var(--text-dim);letter-spacing:0.08em;text-transform:uppercase;}
   306|.vox-channels{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px;}
   307|.vox-channel{
   308|  background:var(--surface);border:1px solid var(--border-dim);border-radius:4px;
   309|  padding:10px 12px;
   310|}
   311|.vox-ch-name{font-size:10px;color:var(--text-muted);margin-bottom:4px;}
   312|.vox-ch-bar{height:3px;background:var(--bg3);border-radius:1px;overflow:hidden;}
   313|.vox-ch-fill{height:100%;background:rgba(186,117,23,0.6);border-radius:1px;}
   314|.vox-insight{
   315|  background:var(--bg3);border:1px solid var(--border-dim);border-radius:4px;
   316|  padding:10px 14px;font-size:10px;color:var(--text-dim);
   317|}
   318|.vox-insight strong{color:var(--amber-mid);}
   319|
   320|/* ═══════════════════ METRICS / PAPER ═══════════════════ */
   321|.metrics-layout{margin-top:60px;}
   322|.metrics-headline{margin-bottom:48px;}
   323|.metrics-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-bottom:48px;}
   324|.metric-card{
   325|  background:var(--bg2);border:1px solid var(--border-dim);border-radius:8px;
   326|  padding:32px 28px;position:relative;overflow:hidden;
   327|}
   328|.metric-card::before{
   329|  content:'';position:absolute;top:0;left:0;right:0;height:2px;
   330|}
